    css: "/* From Uiverse.io by TheAbieza - Tags: flat design, loading, loader, vscode, floating, box-shadow */\n.container {\n  width: fit-content;\n  gap: 10px\n}\n\n.folder {\n  width: min-content;\n  margin: auto;\n  animation: float 2s infinite linear;\n}\n\n.folder .top {\n  background-color: #FF8F56;\n  width: 60px;\n  height: 12px;\n  border-top-right-radius: 10px;\n}\n\n.folder .bottom {\n  background-color: #FFCE63;\n  width: 100px;\n  height: 70px;\n  box-shadow: 5px 5px 0 0 #283149;\n  border-top-right-radius: 8px;\n}\n\n.container .title {\n  font-size: .9em;\n  color: #283149;\n  text-align: center;\n  margin-top: 15px;\n}\n\n@keyframes float {\n  0% {\n    transform: translatey(0px);\n  }\n\n  50% {\n    transform: translatey(-25px);\n  }\n\n  100% {\n    transform: translatey(0px);\n  }\n}",
