    css: "/* From Uiverse.io by pasha43 - Tags: loader, cube, effect loader, loading animation */\n.loader {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  perspective: 800px;\n}\n\n.loader-cube {\n  width: 100px;\n  height: 100px;\n  position: relative;\n  transform-style: preserve-3d;\n  transform-origin: 50% 50%;\n  animation: rotate 4s infinite linear;\n}\n\n.loader-cube:before,\n.loader-cube:after {\n  content: \"\";\n  position: absolute;\n  width: 100%;\n  height: 100%;\n  background-color: transparent;\n}\n\n.loader-cube:before {\n  transform: rotateX(90deg) translateZ(50px);\n}\n\n.loader-cube:after {\n  transform: rotateY(90deg) translateZ(50px);\n}\n\n.loader-cube .face {\n  position: absolute;\n  width: 100%;\n  height: 100%;\n  background-color: rgb(252, 248, 248);\n  opacity: 0.8;\n  border: 2px solid rgb(252, 250, 250);\n}\n\n.loader-cube .face:nth-child(1) {\n  transform: rotateY(0deg) translateZ(50px);\n  background-color: #e74c3c;\n}\n\n.loader-cube .face:nth-child(2) {\n  transform: rotateX(90deg) translateZ(50px);\n  background-color: #3498db;\n}\n\n.loader-cube .face:nth-child(3) {\n  transform: rotateY(180deg) translateZ(50px);\n  background-color: #2ecc71;\n}\n\n.loader-cube .face:nth-child(4) {\n  transform: rotateX(-90deg) translateZ(50px);\n  background-color: #f1c40f;\n}\n\n.loader-cube .face:nth-child(5) {\n  transform: rotateY(90deg) translateZ(50px);\n  background-color: #9b59b6;\n}\n\n.loader-cube .face:nth-child(6) {\n  transform: rotateY(0deg) translateZ(-50px);\n  background-color: #1abc9c;\n}\n\n@keyframes rotate {\n  0% {\n    transform: rotateY(0deg) rotateX(0deg);\n  }\n\n  100% {\n    transform: rotateY(1turn) rotateX(1turn);\n  }\n}",
