    css: "/* From Uiverse.io by AbanoubMagdy1 - Tags: loader */\n.loader {\n  --dim: 5rem;\n  width: var(--dim);\n  height: var(--dim);\n  border: 7px solid #2596be;\n  border-top-color: transparent;\n  border-bottom-color: transparent;\n  border-radius: 50%;\n  animation: spin_51 1.5s infinite linear;\n}\n\n@keyframes spin_51 {\n  from {\n    transform: rotate(0)\n  }\n\n  to {\n    transform: rotate(360deg)\n  }\n}",
