    css: "/* From Uiverse.io by JaydipPrajapati1910 - Tags: green, loader, circle loader, loader circle */\n.loader {\n  background: linear-gradient(to right, #2cc16f 50%, #fafafa 50%);\n  border-radius: 100%;\n  height: 70px;\n  width: 70px;\n  animation: loader-circle-time 8s steps(800, start) infinite;\n}\n\n.loader:after {\n  content: \"\";\n  border-radius: 100% 0 0 100% / 50% 0 0 50%;\n  height: 100%;\n  left: 0;\n  position: absolute;\n  top: 0;\n  width: 50%;\n  animation: loader-circle-mask 8s steps(250, start) infinite;\n  transform-origin: 100% 50%;\n}\n\n@keyframes loader-circle-time {\n  100% {\n    transform: rotate(360deg);\n  }\n}\n\n@keyframes loader-circle-mask {\n  0% {\n    background: #fafafa;\n    transform: rotate(0deg);\n  }\n\n  50% {\n    background: #fafafa;\n    transform: rotate(-180deg);\n  }\n\n  50.01% {\n    background: #2cc16f;\n    transform: rotate(0deg);\n  }\n\n  100% {\n    background: #2cc16f;\n    transform: rotate(-180deg);\n  }\n}",
