    css: "/* From Uiverse.io by Saiyed-Tanvir - Tags: loader, animated, circle loader, circular */\n.quater {\n  height: 1.5cm;\n  width: 1.5cm;\n  background-color: skyblue;\n  float: left;\n  position: relative;\n  bottom: 1.25cm;\n}\n\n.i {\n  border-top-left-radius: 100%;\n  animation: spin1 2s ease-in-out infinite;\n  transform-origin: 1.5cm 1.5cm;\n}\n\n.ii {\n  border-top-right-radius: 100%;\n  animation: spin2 2s ease-in-out infinite;\n  transform-origin: 0 1.5cm;\n}\n\n@keyframes spin1 {\n  0% {\n    transform: rotateZ(0deg);\n  }\n\n  25% {\n    transform: rotateZ(0deg);\n  }\n\n  50% {\n    transform: rotateZ(180deg);\n  }\n\n  75% {\n    transform: rotateZ(180deg);\n  }\n\n  100% {\n    transform: rotateZ(360deg);\n  }\n}\n\n@keyframes spin2 {\n  0% {\n    transform: rotateZ(0deg);\n  }\n\n  25% {\n    transform: rotateZ(180deg);\n  }\n\n  50% {\n    transform: rotateZ(180deg);\n  }\n\n  75% {\n    transform: rotateZ(360deg);\n  }\n\n  100% {\n    transform: rotateZ(360deg);\n  }\n}",
