    css: "/* From Uiverse.io by VashonG  - Tags: purple, loader, star */\n.star {\n  margin: auto;\n  width: 16em;\n  height: 16em;\n}\n.star__stroke {\n  --dur: 2s;\n  animation: stroke1 var(--dur) linear infinite;\n}\n.star__stroke--2 {\n  animation-name: stroke2;\n  animation-delay: calc(var(--dur) / -2);\n}\n.star__stroke--3 {\n  animation-name: stroke3;\n  animation-direction: reverse;\n}\n.star__stroke--4 {\n  animation-name: stroke4;\n  animation-delay: calc(var(--dur) / -2);\n  animation-direction: reverse;\n}\n\n@keyframes stroke1 {\n  from {\n    stroke-dashoffset: 0;\n  }\n  to {\n    stroke-dashoffset: 124;\n  }\n}\n@keyframes stroke2 {\n  from {\n    stroke-dashoffset: 0;\n  }\n  to {\n    stroke-dashoffset: 248;\n  }\n}\n@keyframes stroke3 {\n  from {\n    stroke-dashoffset: 0;\n  }\n  to {\n    stroke-dashoffset: 372;\n  }\n}\n@keyframes stroke4 {\n  from {\n    stroke-dashoffset: 0;\n  }\n  to {\n    stroke-dashoffset: 496;\n  }\n}",
